  describe("handleTrackerResponse", () => {
    function sendTracker(
      sessionId: string,
      events: Record<string, unknown>[],
      extras: Record<string, unknown> = {},
    ) {
      lastSocket.handlers["tracker"]?.({
        sender_id: sessionId,
        events,
        slots: {},
        stack: [],
        ...extras,
      });
    }

    function currentConversationEvents() {
      const { sessionId, conversationList } = inspectorStore.state;
      return conversationList.find((conversation) => conversation.id === sessionId)?.events ?? [];
    }

    function mountHook() {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          onSessionStart: vi.fn(),
          onReconnectError: vi.fn(),
          useMemoryOnly: true,
        }),
      );
      act(() => lastSocket.handlers["connect"]?.());
    }

    it("ignores tracker updates for a mismatched sender_id", () => {
      mountHook();
      const sessionId = inspectorStore.state.sessionId;

      act(() =>
        sendTracker(
          sessionId,
          [
            { event: "user", text: "hello", timestamp: 1 },
            { event: "bot", text: "hi there", timestamp: 2 },
          ],
          {
            slots: { greeting: "hello" },
            stack: [
              {
                frame_id: "f1",
                flow_id: "greet",
                step_id: "s1",
                collect: undefined,
                utter: undefined,
              },
            ],
          },
        ),
      );

      const eventsBefore = currentConversationEvents();
      expect(eventsBefore.length).toBeGreaterThan(0);
      expect(inspectorStore.state.slots).toEqual({ greeting: "hello" });
      expect(inspectorStore.state.stack).toHaveLength(1);

      act(() =>
        sendTracker(
          "other-session",
          [
            { event: "user", text: "should not appear", timestamp: 3 },
            { event: "bot", text: "ignored", timestamp: 4 },
          ],
          {
            slots: { greeting: "overwritten" },
            stack: [
              {
                frame_id: "f2",
                flow_id: "other_flow",
                step_id: "s2",
                collect: undefined,
                utter: undefined,
              },
            ],
          },
        ),
      );

      expect(currentConversationEvents()).toEqual(eventsBefore);
      expect(inspectorStore.state.slots).toEqual({ greeting: "hello" });
      expect(inspectorStore.state.stack).toHaveLength(1);
      expect(inspectorStore.state.stack[0]?.flowId).toBe("greet");
    });

    it("updates only the live streaming bubble and leaves slots and stack untouched", () => {
      mountHook();
      const sessionId = inspectorStore.state.sessionId;

      act(() =>
        sendTracker(
          sessionId,
          [
            { event: "user", text: "lagged user", timestamp: 1 },
            {
              event: "bot",
              text: "partial…",
              timestamp: 2,
              metadata: { streaming: true },
            },
          ],
          {
            slots: { should_not_apply: true },
            stack: [
              {
                frame_id: "f1",
                flow_id: "should_not_apply",
                step_id: "s1",
                collect: undefined,
                utter: undefined,
              },
            ],
          },
        ),
      );

      const events = currentConversationEvents();
      expect(events).toHaveLength(1);
      expect(events[0]).toMatchObject({
        __typename: "Utterance",
        text: "partial…",
      });
      expect(events[0]).toHaveProperty("metadata.streaming", true);
      expect(inspectorStore.state.slots).toEqual({});
      expect(inspectorStore.state.stack).toEqual([]);
    });

    it("preserves existing non-streaming history when a streaming frame arrives", () => {
      mountHook();
      const sessionId = inspectorStore.state.sessionId;

      act(() =>
        sendTracker(sessionId, [
          { event: "user", text: "hello", timestamp: 1 },
          { event: "bot", text: "hi there", timestamp: 2 },
        ]),
      );

      const historyBefore = currentConversationEvents();
      expect(historyBefore).toHaveLength(2);

      act(() =>
        sendTracker(sessionId, [
          { event: "user", text: "stale prior turn", timestamp: 0 },
          {
            event: "bot",
            text: "streaming reply",
            timestamp: 3,
            metadata: { streaming: true },
          },
        ]),
      );

      const events = currentConversationEvents();
      expect(events).toHaveLength(3);
      expect(events.slice(0, 2)).toEqual(historyBefore);
      expect(events[2]).toMatchObject({
        __typename: "Utterance",
        text: "streaming reply",
      });
      expect(events[2]).toHaveProperty("metadata.streaming", true);
    });

    it("replaces full history and clears the streaming bubble on a normal tracker update", () => {
      mountHook();
      const sessionId = inspectorStore.state.sessionId;

      act(() =>
        sendTracker(sessionId, [
          { event: "user", text: "hello", timestamp: 1 },
          { event: "bot", text: "hi there", timestamp: 2 },
        ]),
      );
      act(() =>
        sendTracker(sessionId, [
          {
            event: "bot",
            text: "partial…",
            timestamp: 3,
            metadata: { streaming: true },
          },
        ]),
      );
      expect(
        currentConversationEvents().some(
          (event) =>
            event.__typename === "Utterance" &&
            Boolean((event.metadata as { streaming?: boolean } | undefined)?.streaming),
        ),
      ).toBe(true);

      act(() =>
        sendTracker(
          sessionId,
          [
            { event: "user", text: "hello", timestamp: 1 },
            { event: "bot", text: "hi there", timestamp: 2 },
            { event: "bot", text: "final reply", timestamp: 4 },
          ],
          {
            slots: { done: true },
            stack: [
              {
                frame_id: "f1",
                flow_id: "done_flow",
                step_id: "end",
                collect: undefined,
                utter: undefined,
              },
            ],
          },
        ),
      );

      const events = currentConversationEvents();
      expect(events).toHaveLength(3);
      expect(
        events.some(
          (event) =>
            event.__typename === "Utterance" &&
            Boolean((event.metadata as { streaming?: boolean } | undefined)?.streaming),
        ),
      ).toBe(false);
      expect(events.map((event) => ("text" in event ? event.text : undefined))).toEqual([
        "hello",
        "hi there",
        "final reply",
      ]);
      expect(inspectorStore.state.slots).toEqual({ done: true });
      expect(inspectorStore.state.stack).toHaveLength(1);
      expect(inspectorStore.state.stack[0]?.flowId).toBe("done_flow");
    });
  });

