  describe("reconnect toast lifecycle", () => {
    const RECONNECT_TOAST_ID = "inspector-bot-reconnect";

    beforeEach(() => {
      mockIsToastVisible.mockReturnValue(false);
    });

    it("creates a single persistent toast on first reconnect_error", () => {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed"));
      });

      expect(mockShowToast).toHaveBeenCalledTimes(1);
      expect(mockShowToast).toHaveBeenCalledWith({
        id: RECONNECT_TOAST_ID,
        title: "Reconnect failed",
        description: "Reconnecting...",
        type: "error",
        duration: Infinity,
      });
    });

    it("does not create duplicate toasts on subsequent reconnect_error events", () => {
      mockIsToastVisible.mockReturnValue(false);

      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed"));
      });

      mockIsToastVisible.mockReturnValue(true);

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed again"));
      });

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed yet again"));
      });

      expect(mockShowToast).toHaveBeenCalledTimes(1);
    });

    it("updates the existing toast on reconnect_failed", () => {
      mockSocketReconnectAttempts = 5;

      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_failed"]?.();
      });

      expect(mockUpdateToast).toHaveBeenCalledWith(RECONNECT_TOAST_ID, {
        title: "Reconnect failed",
        description: "websocket wasn't able to reconnect within 5 attempts",
      });

      mockSocketReconnectAttempts = undefined;
    });

    it("updates toast with generic message when socketReconnectAttempts is undefined", () => {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_failed"]?.();
      });

      expect(mockUpdateToast).toHaveBeenCalledWith(RECONNECT_TOAST_ID, {
        title: "Reconnect failed",
        description: "websocket wasn't able to reconnect ",
      });
    });

    it("dismisses the reconnect toast on session_confirm", () => {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed"));
      });

      act(() => {
        lastSocket.handlers["session_confirm"]?.("session-id");
      });

      expect(mockDismissToast).toHaveBeenCalledWith(RECONNECT_TOAST_ID);
    });

    it("dismisses the reconnect toast on cleanup", () => {
      const { unmount } = renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.io.handlers["reconnect_error"]?.(new Error("Connection failed"));
      });

      unmount();

      expect(mockDismissToast).toHaveBeenCalledWith(RECONNECT_TOAST_ID);
    });

    it("does not include 'max' property in error toasts", () => {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.handlers["error"]?.(new Error("Internal error"));
      });

      const callArgs = mockShowToast.mock.calls[0]?.[0] as Record<string, unknown> | undefined;
      expect(callArgs).toBeDefined();
      expect(callArgs).not.toHaveProperty("max");
    });

    it("does not include 'max' property in disconnect toasts", () => {
      renderHook(() =>
        useBotConnection({
          projectId: "test-project",
          useMemoryOnly: true,
        }),
      );

      act(() => {
        lastSocket.handlers["connect"]?.();
      });

      act(() => {
        lastSocket.handlers["disconnect"]?.("transport close");
      });

      const callArgs = mockShowToast.mock.calls[0]?.[0] as Record<string, unknown> | undefined;
      expect(callArgs).toBeDefined();
      expect(callArgs).not.toHaveProperty("max");
    });
  });
